using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SonadaBeds.Web.Data;using SonadaBeds.Web.Models;
namespace SonadaBeds.Web.Controllers;public class MarketingController(SonadaDbContext db):Controller{[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Newsletter(string email){if(!string.IsNullOrWhiteSpace(email)&&!await db.NewsletterSubscribers.AnyAsync(x=>x.Email==email)){db.NewsletterSubscribers.Add(new NewsletterSubscriber{Email=email.Trim()});await db.SaveChangesAsync();}return RedirectToAction("Index","Home");}[HttpGet]public IActionResult Swatches()=>View();[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Swatches(SwatchRequest request){if(ModelState.IsValid){db.SwatchRequests.Add(request);await db.SaveChangesAsync();return View("SwatchThanks");}return View(request);}}
